# owner: platform
import unittest
from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span

def make_shift(name, day, start, stop):
    return Shift(name, day, Span(start * 60, stop * 60))

class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        shifts = [
            make_shift("Cato", "mon", 9, 12),
            make_shift("Brisa", "mon", 8, 16),
            make_shift("Brisa", "tue", 8, 12),
            make_shift("Cato", "tue", 9, 10)
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Brisa: 2 shifts, 12.0 hours",
                "Cato: 2 shifts, 4.0 hours"
            ]
        )

    def test_one_decimal_and_singular(self):
        shift = Shift("Ana", "wed", Span(540, 625))
        self.assertEqual(
            timesheet_lines([shift]),
            ["Ana: 1 shift, 1.4 hours"]
        )

    def test_ties_break_on_shifts_then_name(self):
        shifts = [
            make_shift("Zed", "mon", 8, 10),
            make_shift("Amy", "mon", 8, 9),
            make_shift("Amy", "tue", 8, 9),
            make_shift("Bob", "mon", 8, 10)
        ]
        lines = timesheet_lines(shifts)
        names = [line.split(":")[0] for line in lines]
        self.assertEqual(names, ["Amy", "Bob", "Zed"])

    def test_empty_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        for blank in ("", "   "):
            good = make_shift("Ana", "mon", 8, 9)
            bad = make_shift(blank, "mon", 8, 9)
            with self.assertRaises(ValueError):
                timesheet_lines([good, bad])

if __name__ == "__main__":
    unittest.main()
